import {dimensions,levels,states,blockers,ensureAssessment,assessmentSummary,validateAssessment} from './assessment-core.mjs';
export class PaperAssessment{
 constructor(intake){this.i=intake;this.activeCriterion='scope';this.message='';}
 field(label,key,value,options={}){const id='assessment-'+key.replaceAll('.','-');return `<div class="field"><label for="${id}">${label}</label>${options.select?`<select id="${id}" data-assessment="${key}">${Object.entries(options.select).map(([v,n])=>`<option value="${v}" ${v===value?'selected':''}>${n}</option>`).join('')}</select>`:options.multiline?`<textarea id="${id}" data-assessment="${key}" placeholder="${options.placeholder||''}">${this.i.esc(value||'')}</textarea>`:`<input id="${id}" data-assessment="${key}" value="${this.i.esc(value||'')}" placeholder="${options.placeholder||''}">`}</div>`;}
 plan(p){const a=ensureAssessment(p),s=assessmentSummary(p),e=v=>this.i.esc(v);return `${a.reproduction?.audit?this.i.reproduction.coverage(a.reproduction.audit,e):''}<div class="assessment-intro"><div><h2>短时核查范围草稿</h2><p>草稿用于安排短时核查。完整实验的清单与覆盖以已绑定计划的核验记录为准。</p></div><span class="quiet-stat">${s.covered} / ${s.core} 项核心实验已关联主张</span></div><div class="plan-layout"><section><div class="form-grid">${this.field('论文版本','paper_version',a.paper_version,{placeholder:'arXiv v2 / 会议最终版'})}${this.field('本次目标层级','target',a.target,{select:levels})}</div><div class="section-heading"><h2>结论与实验覆盖</h2><button class="btn" data-paper="add-experiment">添加实验</button></div>${a.experiments.length?a.experiments.map(x=>`<details class="experiment-row" open><summary>${e(x.title||'新实验')} <span>${levels[x.level]}</span></summary><div class="experiment-editor"><div class="form-grid">${this.field('实验 / 图表名称',`experiment.${x.id}.title`,x.title,{placeholder:'Table 2 · CIFAR-10 主结果'})}${this.field('目标层级',`experiment.${x.id}.level`,x.level,{select:levels})}</div>${this.field('支持的论文结论',`experiment.${x.id}.conclusion`,x.conclusion,{multiline:true,placeholder:'方法相对哪些基线，在什么条件下获得何种提升'})}<label class="check-label"><input type="checkbox" data-assessment="experiment.${x.id}.core" ${x.core?'checked':''}>这是支撑主要结论的核心实验</label>${this.field('验收协议',`experiment.${x.id}.protocol`,x.protocol,{multiline:true,placeholder:'数据与指标、作者权重或重新训练、参考结果、种子与统计波动、基线公平性'})}<fieldset class="claim-bindings"><legend>关联实验主张</legend>${p.claims.length?p.claims.map(c=>`<label class="check-label"><input type="checkbox" data-assessment="experiment.${x.id}.claim_ids" value="${e(c.id)}" ${x.claim_ids.includes(c.id)?'checked':''}>${e(c.text||'待编辑主张')}</label>`).join(''):'先在「实验主张」中准备检查项。'}</fieldset><button class="btn text danger" data-paper="remove-experiment" data-id="${x.id}">移除此实验</button></div></details>`).join(''):`<div class="assessment-empty"><h3>先列出论文要验证的实验</h3><p>核心方法、重要基线与消融分别登记。未登记的实验不计入已覆盖范围。</p><button class="btn" data-paper="add-experiment">登记首个实验</button></div>`}</section><aside class="assessment-aside"><h2>四个复现层级</h2>${Object.entries(levels).map(([k,n])=>`<section><h3>${n}</h3><p>${{run:'流程完成并产生有效输出。',evaluation:'固定作者权重与数据，重新计算指标。',training:'从声明的初始化重新训练，再评估结果。',conclusion:'关键基线、对比与消融支持论文主要主张。'}[k]}</p></section>`).join('')}<p class="small-note">这里登记目标与验收方案；层级达成需要相应执行与统计证据。</p><button class="btn" data-intake="step" data-step="criteria">检查复现条件 →</button></aside></div>`;}
 criteria(p){const a=ensureAssessment(p),s=assessmentSummary(p),id=this.activeCriterion,c=a.criteria[id],d=dimensions.find(x=>x[0]===id),e=v=>this.i.esc(v);return `<div class="assessment-intro"><div><h2>公开材料是否足以独立复现</h2><p>${s.documented} 项已记录依据 · ${s.blocked} 项存在阻塞 · ${s.remaining} 项未核查</p></div><button class="btn" data-paper="save-review">保存检查记录</button></div>${this.message?`<div class="info-strip" role="status">${e(this.message)}</div>`:''}<div class="criteria-layout"><div class="criteria-index" role="group" aria-label="八项复现条件">${dimensions.map(([key,title,hint])=>`<button data-paper="criterion" data-id="${key}" class="criterion-item ${id===key?'selected':''}" aria-pressed="${id===key}"><span><strong>${title}</strong><small>${hint}</small></span><span class="criterion-state ${a.criteria[key].status==='blocked'?'warning':''}">${states[a.criteria[key].status]}</span></button>`).join('')}</div><section class="criterion-detail"><h2>${d[1]}</h2><p class="section-description">${d[2]}</p>${this.field('核查状态',`criterion.${id}.status`,c.status,{select:states})}${this.field('证据位置与核查说明',`criterion.${id}.evidence`,c.evidence,{multiline:true,placeholder:'记录论文页码、commit / 文件路径、构建日志、数据校验和；不适用时说明原因'})}${this.i.resourceInspector.material(p,id)}<p class="small-note">材料线索、人工记录与实际执行证据分开保留。记录依据不等于实验已经通过。</p><button class="btn" data-intake="step" data-step="readiness">查看本地运行条件 →</button></section></div><section class="independent-review"><div class="section-heading"><div><h2>干净环境下的独立复现</h2><p class="section-description">记录额外询问、手工修补和阻塞，保留从 README 出发的真实路径。</p></div><button class="btn" data-paper="add-obstacle">记录阻塞</button></div><div class="form-grid">${this.field('复现者 / 审核人','independent.reviewer',a.independent.reviewer,{placeholder:'未参与原项目的复现者'})}${this.field('环境与执行记录位置','independent.environment',a.independent.environment,{placeholder:'镜像 digest、机器规格、日志路径'})}</div><label class="check-label"><input type="checkbox" data-assessment="independent.from_readme" ${a.independent.from_readme?'checked':''}>从干净环境出发，仅按公开 README 开始尝试</label>${this.field('独立复现记录','independent.notes',a.independent.notes,{multiline:true,placeholder:'实际步骤、额外指导、补丁和可重放记录；请勿填写密码或密钥'})}${a.obstacles.map(o=>`<div class="obstacle-row"><div class="form-grid">${this.field('阻塞类型',`obstacle.${o.id}.kind`,o.kind,{select:blockers})}${this.field('问题与证据',`obstacle.${o.id}.note`,o.note,{placeholder:'卡在哪一步、对应日志、需要什么帮助'})}</div><button class="btn text danger" data-paper="remove-obstacle" data-id="${o.id}">移除记录</button></div>`).join('')}</section>`;}
 result(p){const a=ensureAssessment(p),s=assessmentSummary(p);return `<section class="paper-result-summary"><div><h2>复现目标与覆盖范围</h2><p>目标：${levels[a.target]} · ${this.i.esc(a.paper_version||'论文版本待登记')}</p></div><div><strong>${s.covered} / ${s.core}</strong><span>核心实验已关联主张</span></div><div><strong>${s.documented} / 8</strong><span>条件已记录依据</span></div></section>${a.experiments.length?`<div class="experiment-coverage">${a.experiments.map(x=>`<div><strong>${this.i.esc(x.title||'未命名实验')}</strong><span>${levels[x.level]} · ${x.core?'核心实验':'补充实验'}</span><p>${this.i.esc(x.conclusion||'结论待登记')}</p><small>${x.claim_ids.length} 条关联主张 · 层级尚未独立验收</small></div>`).join('')}</div>`:`<p class="info-strip">核心实验清单尚未登记，当前报告仅覆盖选定 probe 检查。</p>`}<p class="assessment-boundary">短时 probe 结果用于下方检查项判定。训练与主要结论复现需要完整实验、基线及统计证据。</p>`;}
 bind(){const edit=async ev=>{const el=ev.target;if(!el.dataset.assessment)return;const p=this.i.current(),a=ensureAssessment(p),parts=el.dataset.assessment.split('.');let obj=a,key=parts.at(-1);if(parts[0]==='experiment')obj=a.experiments.find(x=>x.id===parts[1]);else if(parts[0]==='criterion')obj=a.criteria[parts[1]];else if(parts[0]==='independent')obj=a.independent;else if(parts[0]==='obstacle')obj=a.obstacles.find(x=>x.id===parts[1]);if(!obj)return;if(parts[0]==='criterion'&&key==='status'&&el.value!=='unreviewed'&&!obj.evidence.trim()){this.message='先填写证据或原因，再更新核查状态。';this.i.h.render();return;}if(key==='claim_ids'){obj[key]=obj[key].filter(x=>x!==el.value);if(el.checked)obj[key].push(el.value);}else obj[key]=el.type==='checkbox'?el.checked:el.value;await this.i.save(p);if(parts[0]==='criterion'&&key==='status')this.i.h.render();};document.addEventListener('change',edit);document.addEventListener('input',ev=>{if(ev.target.matches('input:not([type=checkbox]),textarea'))edit(ev);});document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-paper]');if(!el)return;const p=this.i.current(),a=ensureAssessment(p);switch(el.dataset.paper){case'criterion':this.activeCriterion=el.dataset.id;this.message='';break;case'add-experiment':a.experiments.push({id:crypto.randomUUID(),title:'',conclusion:'',core:true,level:a.target,protocol:'',claim_ids:[]});break;case'remove-experiment':a.experiments=a.experiments.filter(x=>x.id!==el.dataset.id);break;case'add-obstacle':a.obstacles.push({id:crypto.randomUUID(),kind:'materials',note:''});break;case'remove-obstacle':a.obstacles=a.obstacles.filter(x=>x.id!==el.dataset.id);break;case'save-review':try{validateAssessment(a);this.message='检查记录已保存；不替代实验验收。';}catch(e){this.message=e.message;}break;}await this.i.save(p);this.i.h.render();});}
}
